test-code.code:
import org.apache.http.impl.client.HttpClients

class Bad {
    fun doRequest(url: String) {
        val client = HttpClients.custom().build() // bad: recreated per call
    }
}

import org.apache.http.impl.client.HttpClientBuilder

class Bad {
    fun buildClient() = HttpClientBuilder.create().build() // bad: single-expression, recreated per call
}

import org.apache.http.impl.client.HttpClients

class Bad {
    fun doRequests(urls: List<String>) = urls.map { url ->
        HttpClients.custom().build() // bad: new client per iteration
    }
}

import org.apache.http.impl.client.HttpClients

class Good {
    companion object {
        private val HTTP_CLIENT = HttpClients.custom().build() // ok: created once
    }
    fun doRequest(url: String) = HTTP_CLIENT.execute(org.apache.http.client.methods.HttpGet(url))
}
